export {
  ErrorState,
  ErrorStateActions,
  ErrorStateContent,
  ErrorStateDescription,
  ErrorStateHeader,
  ErrorStateMedia,
  ErrorStateTitle,
} from "./error-state-base";
export type { ErrorStateProps } from "./error-state-base";
export { ErrorStateDetails } from "./error-state-details";
export type { ErrorStateDetailsProps } from "./error-state-details";

import { cn } from "cn";
import type * as React from "react";

type ErrorStateProps = React.ComponentProps<"div"> & {
  border?: "none" | "solid" | "dashed";
  variant?: "centered" | "inline";
};

const ErrorState = ({
  className,
  border = "none",
  variant = "centered",
  ...props
}: ErrorStateProps) => (
  <div
    data-slot="error-state"
    data-variant={variant}
    data-border={border}
    className={cn(
      "group/error-state flex w-full min-w-0 gap-4 rounded-xl text-foreground",
      border === "solid" && "border border-solid",
      border === "dashed" && "border border-dashed",
      variant === "inline"
        ? "items-start p-4 text-start"
        : "flex-col items-center justify-center p-6 text-center",
      className
    )}
    {...props}
  />
);

const ErrorStateMedia = ({
  className,
  ...props
}: React.ComponentProps<"div">) => (
  <div
    data-slot="error-state-media"
    className={cn(
      "flex size-9 shrink-0 items-center justify-center rounded-lg bg-destructive/10 text-destructive [&_svg]:size-5 [&_svg]:shrink-0",
      className
    )}
    {...props}
  />
);

const ErrorStateContent = ({
  className,
  ...props
}: React.ComponentProps<"div">) => (
  <div
    data-slot="error-state-content"
    className={cn(
      "flex w-full min-w-0 max-w-sm flex-col gap-4 group-data-[variant=inline]/error-state:max-w-none",
      className
    )}
    {...props}
  />
);

const ErrorStateHeader = ({
  className,
  ...props
}: React.ComponentProps<"div">) => (
  <div
    data-slot="error-state-header"
    className={cn("flex min-w-0 flex-col gap-2", className)}
    {...props}
  />
);

const ErrorStateTitle = ({
  className,
  ...props
}: React.ComponentProps<"div">) => (
  <div
    data-slot="error-state-title"
    className={cn(
      "text-sm font-medium tracking-tight wrap-anywhere text-balance",
      className
    )}
    {...props}
  />
);

const ErrorStateDescription = ({
  className,
  ...props
}: React.ComponentProps<"div">) => (
  <div
    data-slot="error-state-description"
    className={cn(
      "text-sm/relaxed text-muted-foreground wrap-anywhere",
      className
    )}
    {...props}
  />
);

const ErrorStateActions = ({
  className,
  ...props
}: React.ComponentProps<"div">) => (
  <div
    data-slot="error-state-actions"
    className={cn(
      "flex min-w-0 flex-wrap items-center justify-center gap-2 group-data-[variant=inline]/error-state:justify-start",
      className
    )}
    {...props}
  />
);

export {
  ErrorState,
  ErrorStateActions,
  ErrorStateContent,
  ErrorStateDescription,
  ErrorStateHeader,
  ErrorStateMedia,
  ErrorStateTitle,
};
export type { ErrorStateProps };

"use client";

import { cn } from "cn";
import { MinusIcon, PlusIcon } from "lucide-react";
import type * as React from "react";

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "./accordion";
import type { AccordionTriggerProps } from "./accordion";

type ErrorStateDetailsProps = Omit<
  React.ComponentProps<"div">,
  "onToggle" | "defaultValue"
> & {
  summary?: React.ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  disabled?: boolean;
  icon?: AccordionTriggerProps["icon"];
  expandedIcon?: AccordionTriggerProps["expandedIcon"];
};

const ErrorStateDetails = ({
  className,
  summary = "Technical details",
  children,
  open,
  defaultOpen = false,
  onOpenChange,
  disabled = false,
  icon = <PlusIcon />,
  expandedIcon = <MinusIcon />,
  ...props
}: ErrorStateDetailsProps) => (
  <Accordion<string>
    {...props}
    data-slot="error-state-details"
    className={cn(
      "min-w-0 text-start text-xs text-muted-foreground",
      className
    )}
    value={open === undefined ? undefined : ["details"].filter(() => open)}
    defaultValue={defaultOpen ? ["details"] : []}
    onValueChange={(values) => onOpenChange?.(values.includes("details"))}
    disabled={disabled}
  >
    <AccordionItem value="details">
      <AccordionTrigger
        icon={icon}
        expandedIcon={expandedIcon}
        className="items-center py-1 text-xs font-normal text-muted-foreground hover:text-foreground"
      >
        {summary}
      </AccordionTrigger>
      <AccordionContent className="pt-2 pb-0">
        <div
          className="max-h-40 overflow-y-auto rounded-md bg-muted/40 p-3 font-mono whitespace-pre-wrap wrap-anywhere focus-visible:outline-2 focus-visible:outline-ring"
          // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex -- Keep overflowing support information keyboard-scrollable.
          tabIndex={0}
        >
          {children}
        </div>
      </AccordionContent>
    </AccordionItem>
  </Accordion>
);

export { ErrorStateDetails };
export type { ErrorStateDetailsProps };
